function matcha(text){
  // Exakt-matchning: bara ett meddelande som AR nyckelordet triggar autosvaret.
  // Skyddar mot att t.ex. "denna vecka" i en prospekt-trad smaller igang demot.
  const norm=String(text||'').toLowerCase().replace(/[^a-zåäö]/g,'');
  for(const [kw,s] of Object.entries(SVAR)){ if(norm===kw) return {kw,svar:s}; }
  return null;
}

const out=[];
for(const item of $input.all()){
  const body=item.json.body||item.json;
  for(const entry of (body.entry||[])){
    for(const ev of (entry.messaging||[])){
      const msg=ev.message;
      if(!msg||!msg.text||msg.is_echo) continue;
      const hit=matcha(msg.text);
      if(!hit) continue;
      out.push({json:{typ:'dm', recipient:{id:ev.sender.id}, reply_text:hit.svar, keyword:hit.kw, token:IG_ACCESS_TOKEN}});
    }
    for(const ch of (entry.changes||[])){
      if(ch.field!=='comments') continue;
      const v=ch.value||{};
      if(v.from && v.from.id===entry.id) continue;
      const hit=matcha(v.text);
      if(!hit) continue;
      out.push({json:{typ:'comment', recipient:{comment_id:v.id}, reply_text:hit.svar, keyword:hit.kw, token:IG_ACCESS_TOKEN}});
    }
  }
}
return out;

// SCC-loggning: ALLA meddelanden (inbound + echoes av egna skickade)
const IG_ACCESS_TOKEN = 'IGAA3dA6X9qcNBZAGF1Sk5qdWtZARkc2UHh1dGtPMU5vVVphWDRfZAmlqMGdHaF9kdFdDWFVENDh6a01KRjZARYkNvb1M3RGRYNktNTWZAkaDNBWFdmZAHBFWnZAsdHJkdEJZAV2dHbnJIcjFQblZAQZAGtxM2hob01VcjBsazFVMXF5dUNXNAZDZD';
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const entry of (body.entry || [])) {
    for (const ev of (entry.messaging || [])) {
      const msg = ev.message;
      if (!msg || !msg.text) continue;
      const echo = !!msg.is_echo;
      const other = echo ? (ev.recipient && ev.recipient.id) : (ev.sender && ev.sender.id);
      if (!other) continue;
      out.push({ json: {
        ig_id: String(other),
        direction: echo ? 'outbound' : 'inbound',
        text: msg.text,
        mid: msg.mid || '',
        timestamp: ev.timestamp || Date.now(),
        token: IG_ACCESS_TOKEN,
      } });
    }
  }
}
return out;

// Para ihop username-svaret med ursprungsdatat (indexordning bevaras)
const extr = $('SCC-extrakt').all();
const out = [];
const inp = $input.all();
for (let i = 0; i < inp.length; i++) {
  const resp = inp[i].json || {};
  const src = (extr[i] || {}).json || {};
  if (!src.text) continue;
  out.push({ json: {
    username: resp.username || '',
    ig_id: src.ig_id || '',
    direction: src.direction,
    text: src.text,
    mid: src.mid,
    timestamp: src.timestamp,
  } });
}
return out;
